"use client"

import { useSyncExternalStore } from "react"

function subscribe(onStoreChange: () => void) {
  const media = window.matchMedia("(prefers-reduced-motion: reduce)")
  media.addEventListener("change", onStoreChange)
  return () => media.removeEventListener("change", onStoreChange)
}

function getSnapshot() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getServerSnapshot() {
  return false
}

export function usePrefersReducedMotion() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot)
}

import { Mesh, Program, Renderer, Triangle } from "ogl"

const vertex = `
attribute vec2 uv;
attribute vec2 position;
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 0.0, 1.0);
}
`

const fragment = `
precision highp float;
uniform float uTime;
uniform vec2 uResolution;
varying vec2 vUv;

void main() {
  vec2 uv = gl_FragCoord.xy / uResolution.xy;
  float y = uv.y;
  vec3 top = vec3(0.025, 0.03, 0.045);
  vec3 mid = vec3(0.07, 0.055, 0.07);
  vec3 col = mix(top, mid, smoothstep(0.0, 0.72, y));

  float horizon = 0.33 + 0.012 * sin(uv.x * 5.5 + uTime * 0.18);
  float heat = exp(-pow((y - horizon) * 8.5, 2.0));
  col += vec3(0.96, 0.78, 0.55) * heat * 0.5;
  col += vec3(0.82, 0.38, 0.16) * exp(-pow((y - horizon) * 3.0, 2.0)) * 0.42;

  float ribbon = sin(uv.x * 3.2 + uTime * 0.24) * 0.055;
  float rib = exp(-pow((y - (horizon + 0.09 + ribbon)) * 16.0, 2.0));
  col += vec3(0.32, 0.7, 0.66) * rib * 0.5;

  float ribbonB = sin(uv.x * 6.0 - uTime * 0.16 + 1.4) * 0.04;
  float ribB = exp(-pow((y - (horizon + 0.18 + ribbonB)) * 22.0, 2.0));
  col += vec3(0.78, 0.42, 0.24) * ribB * 0.38;

  float veil = smoothstep(0.48, 0.0, abs(fract(uv.x * 8.0 + sin(uTime * 0.07 + y * 2.2)) - 0.5));
  col += vec3(0.45, 0.75, 0.7) * veil * smoothstep(horizon, horizon + 0.5, y) * 0.045 * (1.0 - y);

  float grain = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233)) + uTime * 12.0) * 43758.5453);
  col += (grain - 0.5) * 0.04;

  vec2 vigUv = (uv - 0.5) * vec2(1.15, 1.0);
  col *= smoothstep(1.2, 0.28, length(vigUv));

  gl_FragColor = vec4(col, 1.0);
}
`

export function mountHorizonVeil(canvas: HTMLCanvasElement) {
  const renderer = new Renderer({
    canvas,
    alpha: false,
    antialias: false,
    dpr: Math.min(window.devicePixelRatio || 1, 1.5),
  })
  const gl = renderer.gl
  gl.clearColor(0.03, 0.035, 0.05, 1)

  const geometry = new Triangle(gl)
  const program = new Program(gl, {
    vertex,
    fragment,
    uniforms: {
      uTime: { value: 0 },
      uResolution: { value: [1, 1] },
    },
  })
  const mesh = new Mesh(gl, { geometry, program })

  const resize = () => {
    const parent = canvas.parentElement
    const rect = parent?.getBoundingClientRect()
    const width = Math.max(1, rect?.width ?? window.innerWidth)
    const height = Math.max(1, rect?.height ?? window.innerHeight)
    renderer.setSize(width, height)
    const resolution = program.uniforms.uResolution
    if (resolution) resolution.value = [canvas.width, canvas.height]
  }

  resize()
  const start = performance.now()
  let frame = 0
  const loop = (now: number) => {
    const time = program.uniforms.uTime
    if (time) time.value = (now - start) / 1000
    renderer.render({ scene: mesh })
    frame = requestAnimationFrame(loop)
  }
  frame = requestAnimationFrame(loop)

  const observer = new ResizeObserver(resize)
  if (canvas.parentElement) observer.observe(canvas.parentElement)

  return () => {
    cancelAnimationFrame(frame)
    observer.disconnect()
    gl.getExtension("WEBGL_lose_context")?.loseContext()
  }
}

"use client"

import { useEffect, useRef, type ReactNode } from "react"
import { usePrefersReducedMotion } from "./use-reduced-motion"

export function HorizonVeil({
  preview = false,
  children,
}: {
  preview?: boolean
  children?: ReactNode
}) {
  const reduced = usePrefersReducedMotion()
  const canvasRef = useRef<HTMLCanvasElement>(null)

  useEffect(() => {
    if (preview || reduced) return
    const canvas = canvasRef.current
    const parent = canvas?.parentElement
    if (!canvas || !parent) return

    let dead = false
    let cleanup = () => {}
    let started = false

    const start = () => {
      if (started || dead) return
      started = true
      void import("./horizon-veil-gl")
        .then((mod) => {
          if (dead) return
          cleanup = mod.mountHorizonVeil(canvas)
        })
        .catch(() => {
          canvas.style.display = "none"
        })
    }

    const observer = new IntersectionObserver(([entry]) => {
      if (entry?.isIntersecting) {
        observer.disconnect()
        start()
      }
    })
    observer.observe(parent)

    return () => {
      dead = true
      cleanup()
      observer.disconnect()
    }
  }, [preview, reduced])

  return (
    <section
      aria-label="Horizon veil background"
      className={
        preview
          ? "relative h-full overflow-hidden bg-[#07090e] text-[#f6f1e8]"
          : "relative min-h-[100svh] overflow-hidden bg-[#07090e] text-[#f6f1e8]"
      }
    >
      <style>{`
        @keyframes mk-horizon-rise {
          0% { transform: translate3d(0, 8px, 0) scale(1); opacity: 0.7; }
          50% { transform: translate3d(0, -10px, 0) scale(1.04); opacity: 1; }
          100% { transform: translate3d(0, 8px, 0) scale(1); opacity: 0.7; }
        }
        @media (prefers-reduced-motion: reduce) {
          .mk-horizon-band { animation: none !important; }
        }
      `}</style>
      <div aria-hidden className="absolute inset-0 bg-[linear-gradient(#07090e,#121018_58%,#07090e)]" />
      <div
        aria-hidden
        className="mk-horizon-band absolute inset-x-[-10%] bottom-[18%] h-40 bg-[radial-gradient(ellipse_at_center,rgba(242,196,130,0.85),rgba(176,78,32,0.35)_42%,transparent_70%)] blur-2xl"
        style={{ animation: reduced ? undefined : "mk-horizon-rise 9s ease-in-out infinite" }}
      />
      <div
        aria-hidden
        className="absolute inset-x-0 bottom-[30%] h-px bg-gradient-to-r from-transparent via-[#f3d7a8] to-transparent"
      />
      <div
        aria-hidden
        className="absolute inset-0 opacity-60"
        style={{
          backgroundImage:
            "repeating-linear-gradient(90deg, transparent 0 42px, rgba(120,190,184,0.08) 42px 43px)",
          maskImage: "linear-gradient(to top, transparent 20%, black 48%, transparent 90%)",
        }}
      />
      <canvas ref={canvasRef} aria-hidden className="absolute inset-0 h-full w-full" />
      <div className={preview ? "relative z-10 flex h-full flex-col justify-end p-5" : "relative z-10 flex min-h-[100svh] flex-col justify-end px-6 py-16 md:px-12"}>
        {children ?? (
          <div>
            <p className="text-[10px] tracking-[0.32em] text-[#f0c48a] uppercase">Horizon Veil</p>
            <h2
              className={preview ? "mt-2 max-w-xs font-serif text-4xl leading-[0.92]" : "mt-3 max-w-2xl font-serif text-6xl leading-[0.92] md:text-7xl"}
              style={{ fontFamily: "var(--font-serif), Georgia, serif" }}
            >
              Night, and a line of heat.
            </h2>
          </div>
        )}
      </div>
    </section>
  )
}
